function formatDescription(value){const source=String(value||'').replace(/\r\n?/g,'\n').trim();if(!source)return '<p>'+esc(t('common.notSpecified'))+'</p>';const inline=text=>esc(text).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>'),lines=source.split('\n');let html='',paragraph=[],listType='';const flushParagraph=()=>{if(!paragraph.length)return;html+='<p>'+paragraph.map(inline).join('<br>')+'</p>';paragraph=[];};const closeList=()=>{if(!listType)return;html+='</'+listType+'>';listType='';};for(const rawLine of lines){const line=rawLine.trimEnd();if(!line.trim()){flushParagraph();closeList();continue;}const heading=line.match(/^(#{1,3})\s+(.+)$/),unordered=line.match(/^\s*[-*]\s+(.+)$/),ordered=line.match(/^\s*\d+[.)]\s+(.+)$/);if(heading){flushParagraph();closeList();const level=Math.min(5,heading[1].length+2);html+='<h'+level+'>'+inline(heading[2])+'</h'+level+'>';continue;}if(unordered||ordered){flushParagraph();const type=unordered?'ul':'ol';if(listType!==type){closeList();html+='<'+type+'>';listType=type;}html+='<li>'+inline((unordered||ordered)[1])+'</li>';continue;}closeList();paragraph.push(line.trim());}flushParagraph();closeList();return html;}
