function vehicleCoverIndex(vehicle){if(!vehicle)return 0;if(REMOTE_MODE){const index=(vehicle.image_ids||[]).findIndex(id=>Number(id)===Number(vehicle.cover_image_id));return index>=0?index:0;}const index=Number(vehicle.cover_image_index);return Number.isInteger(index)&&index>=0&&index<vehicleImageCount(vehicle)?index:0;}
