const TOAST_META={success:{icon:'✓',title:'toast.titleSuccess'},error:{icon:'!',title:'toast.titleError'},warning:{icon:'!',title:'toast.titleWarning'},info:{icon:'i',title:'toast.titleInfo'}};
function toast(text,type='info',options={}){const region=q('#toast-region'),kind=TOAST_META[type]?type:'info';if(!region||!text)return null;const item=document.createElement('section'),meta=TOAST_META[kind],duration=Number(options.duration)||4800;item.className='ntc-toast ntc-toast-'+kind;item.setAttribute('role',kind==='error'?'alert':'status');item.innerHTML='<span class="ntc-toast-icon" aria-hidden="true">'+meta.icon+'</span><span class="ntc-toast-copy"><strong>'+esc(options.title||t(meta.title))+'</strong><span>'+esc(text)+'</span></span><button class="ntc-toast-close" type="button" aria-label="'+esc(t('toast.dismiss'))+'">×</button>';const dismiss=()=>{if(item.classList.contains('is-leaving'))return;item.classList.add('is-leaving');setTimeout(()=>item.remove(),220);};item.querySelector('.ntc-toast-close').addEventListener('click',dismiss);region.appendChild(item);while(region.children.length>4)region.firstElementChild.remove();requestAnimationFrame(()=>item.classList.add('is-visible'));if(duration>0)setTimeout(dismiss,duration);return item;}
toast.success=(text,options)=>toast(text,'success',options);toast.error=(text,options)=>toast(text,'error',options);toast.warning=(text,options)=>toast(text,'warning',options);toast.info=(text,options)=>toast(text,'info',options);
let actionDialogResolve=null,actionDialogAction=null,actionDialogOpener=null,actionDialogPending=false,actionDialogConfirmLabel='';
const actionDialog=()=>q('#action-dialog');
function actionDialogFocusables(){const dialog=actionDialog();return dialog?[...dialog.querySelectorAll('button:not([disabled]),[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')].filter(element=>!element.hidden&&element.offsetParent!==null):[];}
function resetActionDialogPending(){const dialog=actionDialog(),confirm=q('#action-dialog-confirm'),cancel=q('#action-dialog-cancel');actionDialogPending=false;if(dialog)dialog.querySelector('.action-dialog-panel')?.setAttribute('aria-busy','false');if(confirm){confirm.disabled=false;confirm.classList.remove('is-loading');confirm.textContent=actionDialogConfirmLabel;}if(cancel)cancel.disabled=false;}
function settleActionDialog(result){const dialog=actionDialog(),resolve=actionDialogResolve,opener=actionDialogOpener;if(!dialog||!resolve)return;dialog.classList.remove('open');dialog.setAttribute('aria-hidden','true');resetActionDialogPending();actionDialogResolve=null;actionDialogAction=null;actionDialogOpener=null;if(!document.querySelector('.modal.open:not(.route-mounted)'))document.body.style.overflow='';setTimeout(()=>{if(opener&&document.contains(opener))opener.focus();resolve(result);},180);}
function cancelActionDialog(){if(!actionDialogPending)settleActionDialog(false);}
async function acceptActionDialog(){if(actionDialogPending||!actionDialogResolve)return;if(typeof actionDialogAction!=='function'){settleActionDialog(true);return;}const dialog=actionDialog(),confirm=q('#action-dialog-confirm'),cancel=q('#action-dialog-cancel'),errorBox=q('#action-dialog-error');actionDialogPending=true;dialog.querySelector('.action-dialog-panel')?.setAttribute('aria-busy','true');confirm.disabled=true;cancel.disabled=true;confirm.classList.add('is-loading');confirm.textContent=t('dialog.processing');errorBox.hidden=true;try{await actionDialogAction();settleActionDialog(true);}catch(error){resetActionDialogPending();errorBox.textContent=error?.message||t('dialog.actionFailed');errorBox.hidden=false;toast.error(errorBox.textContent);confirm.focus();}}
function openActionDialog(options={},action=null){if(actionDialogResolve)return Promise.resolve(false);const dialog=actionDialog(),tone=['danger','warning','default'].includes(options.tone)?options.tone:'default';actionDialogOpener=document.activeElement;actionDialogAction=action;actionDialogConfirmLabel=options.confirmLabel||t('dialog.confirm');dialog.dataset.tone=tone;q('#action-dialog-title').textContent=options.title||t('dialog.confirmTitle');q('#action-dialog-message').textContent=options.message||'';const detail=q('#action-dialog-detail');detail.textContent=options.detail||'';detail.hidden=!options.detail;q('#action-dialog-error').hidden=true;q('#action-dialog-cancel').textContent=options.cancelLabel||t('common.cancel');q('#action-dialog-confirm').textContent=actionDialogConfirmLabel;dialog.setAttribute('aria-hidden','false');dialog.classList.add('open');document.body.style.overflow='hidden';return new Promise(resolve=>{actionDialogResolve=resolve;requestAnimationFrame(()=>q('#action-dialog-cancel').focus());});}
const confirmDialog=options=>openActionDialog(options);
const confirmAction=(options,action)=>openActionDialog(options,action);
q('#action-dialog-confirm').addEventListener('click',acceptActionDialog);
q('#action-dialog').addEventListener('click',event=>{if(event.target.closest('[data-dialog-cancel]'))cancelActionDialog();});
document.addEventListener('keydown',event=>{const dialog=actionDialog();if(!dialog?.classList.contains('open'))return;if(event.key==='Escape'){event.preventDefault();cancelActionDialog();return;}if(event.key!=='Tab')return;const focusable=actionDialogFocusables();if(!focusable.length){event.preventDefault();dialog.querySelector('.action-dialog-panel')?.focus();return;}const first=focusable[0],last=focusable[focusable.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}});
let compactModalOpener=null;
function focusableWithin(root){return [...root.querySelectorAll('button:not([disabled]),[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')].filter(element=>!element.hidden&&element.offsetParent!==null);}
function modal(id){const target=q(id);if(!target)return;compactModalOpener=document.activeElement;target.classList.add('open');target.setAttribute('aria-hidden','false');if(!target.hasAttribute('role')){target.setAttribute('role','dialog');target.setAttribute('aria-modal','true');const heading=target.querySelector('h1,h2,h3');if(heading){if(!heading.id)heading.id=target.id+'-title';target.setAttribute('aria-labelledby',heading.id);}}const panel=target.querySelector('.modal-panel,.lightbox-panel');if(panel&&!panel.hasAttribute('tabindex'))panel.tabIndex=-1;document.body.style.overflow='hidden';requestAnimationFrame(()=>{const preferred=target.querySelector('.close-modal,.lightbox-close,input:not([type="hidden"]),textarea,button,a[href]');(preferred||panel)?.focus();});}
function close(){const settings=q('#settings-modal');if(settings?.classList.contains('open')&&settingsOriginalAppearance){applyAppearance({appearance:settingsOriginalAppearance});settingsOriginalAppearance=null;}const dialogs=[...document.querySelectorAll('.modal.open:not(.route-mounted)')];dialogs.forEach(dialog=>{dialog.classList.remove('open');dialog.setAttribute('aria-hidden','true');});document.body.style.overflow='';if(document.fullscreenElement&&document.fullscreenElement.closest?.('#image-lightbox'))document.exitFullscreen().catch(()=>{});const opener=compactModalOpener;compactModalOpener=null;if(dialogs.length&&opener&&document.contains(opener))requestAnimationFrame(()=>opener.focus());}
