let settingsOriginalAppearance=null;
function validHexColor(value){return /^#[0-9a-f]{6}$/i.test(String(value||''));}
function normalizeAppearance(value){if(value==='oled-blue'||value==='oled-ice')return value;if(/^custom:#[0-9a-f]{6}$/i.test(String(value||'')))return 'custom:'+value.slice(7).toUpperCase();return 'oled-blue';}
function appearanceHex(value){const appearance=normalizeAppearance(value);if(appearance==='oled-blue')return '#2F98FF';if(appearance==='oled-ice')return '#9BEEFF';return appearance.slice(7);}
function hexChannels(hex){return [1,3,5].map(index=>parseInt(hex.slice(index,index+2),16));}
function lightenHex(hex,amount=.28){return '#'+hexChannels(hex).map(channel=>Math.round(channel+(255-channel)*amount).toString(16).padStart(2,'0')).join('').toUpperCase();}
function readableAccentInk(hex){const values=hexChannels(hex).map(channel=>{const value=channel/255;return value<=.03928?value/12.92:Math.pow((value+.055)/1.055,2.4);});return .2126*values[0]+.7152*values[1]+.0722*values[2]>.42?'#001218':'#F7FBFF';}
function applyAppearance(profile){const appearance=normalizeAppearance(profile?.appearance),root=document.documentElement,custom=appearance.startsWith('custom:');root.setAttribute('data-appearance',custom?'custom':appearance);for(const property of ['--accent','--accent-rgb','--accent-hover','--accent-ink'])root.style.removeProperty(property);if(custom){const hex=appearanceHex(appearance),rgb=hexChannels(hex);root.style.setProperty('--accent',hex);root.style.setProperty('--accent-rgb',rgb.join(','));root.style.setProperty('--accent-hover',lightenHex(hex));root.style.setProperty('--accent-ink',readableAccentInk(hex));}}
function accentSwatches(){return ACCENT_PRESETS.map(item=>'<button type="button" class="accent-swatch" data-accent="'+item.value+'" style="--swatch:'+item.color+'" aria-label="'+item.label+'" title="'+item.label+'"><span></span></button>').join('');}
function setAppearanceControls(value,preview=false){const appearance=normalizeAppearance(value),hex=appearanceHex(appearance);q('#settings-appearance').value=appearance;q('#accent-color').value=hex.toLowerCase();q('#accent-hex').value=hex;document.querySelectorAll('[data-accent]').forEach(button=>{const active=button.dataset.accent.toLowerCase()===appearance.toLowerCase();button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});if(preview)applyAppearance({appearance});}
function applyUserPreferences(profile){if(!profile)return;I18N.setPreferences({language:profile.language||I18N.DEFAULT_LANGUAGE,currency:profile.currency||I18N.DEFAULT_CURRENCY},{notify:false});}
function notificationBellIcon(){return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>';}
function notificationMessage(notification){const actor=notification.actor_name||t('notifications.member'),vehicle=notification.resource_label||t('notifications.vehicle');if(notification.event_type==='new_comment')return t('notifications.comment',{actor,vehicle});if(notification.event_type==='new_rating')return t('notifications.rating',{actor,vehicle});if(notification.event_type==='rating_message')return t('notifications.ratingMessage',{actor,vehicle});if(notification.event_type==='listing_published')return t('notifications.published',{vehicle});return t('notifications.generic');}
function relativeNotificationTime(value){const date=new Date(value),seconds=Math.round((date.getTime()-Date.now())/1000);if(Number.isNaN(seconds))return'';const formatter=new Intl.RelativeTimeFormat(I18N.language,{numeric:'auto'}),absolute=Math.abs(seconds);if(absolute<60)return formatter.format(seconds,'second');if(absolute<3600)return formatter.format(Math.round(seconds/60),'minute');if(absolute<86400)return formatter.format(Math.round(seconds/3600),'hour');if(absolute<604800)return formatter.format(Math.round(seconds/86400),'day');return I18N.formatDate(date,{dateStyle:'medium'});}
function notificationIcon(notification){if(notification.event_type==='new_comment')return'✦';if(notification.event_type==='new_rating')return'★';if(notification.event_type==='rating_message')return'↗';return'✓';}
function notificationItemMarkup(notification,history=false){const unread=!notification.is_read,path=notification.url||'',message=notificationMessage(notification),content='<span class="notification-item-icon" aria-hidden="true">'+notificationIcon(notification)+'</span><span class="notification-item-copy"><strong>'+esc(message)+'</strong><time datetime="'+esc(notification.created_at)+'">'+esc(relativeNotificationTime(notification.created_at))+'</time></span>'+(unread?'<span class="notification-item-unread" aria-label="'+esc(t('notifications.unread'))+'"></span>':'');return '<article class="notification-item '+(unread?'is-unread':'is-read')+'" data-notification-row="'+esc(notification.id)+'">'+(path?'<a href="'+esc(path)+'" data-notification-open="'+esc(notification.id)+'">'+content+'</a>':'<div>'+content+'</div>')+(unread?'<button type="button" class="notification-read-button" data-notification-read="'+esc(notification.id)+'">'+esc(t('notifications.markRead'))+'</button>':'')+(history?'':'')+'</article>';}
function notificationPanelContent(){if(notificationRecentPending&&!notificationRecent.length)return '<div class="notification-state">'+esc(t('notifications.loading'))+'</div>';if(notificationRecentError&&!notificationRecent.length)return '<div class="notification-state is-error"><strong>'+esc(t('notifications.error'))+'</strong><button type="button" data-notifications-retry>'+esc(t('notifications.retry'))+'</button></div>';if(!notificationRecent.length)return '<div class="notification-state"><strong>'+esc(t('notifications.empty'))+'</strong><span>'+esc(t('notifications.emptyText'))+'</span></div>';return notificationRecent.map(item=>notificationItemMarkup(item)).join('');}
function notificationCenterMarkup(){return '<div class="notification-center"><button class="notification-bell" type="button" data-notification-toggle aria-haspopup="dialog" aria-expanded="false" aria-label="'+esc(t('notifications.open',{count:notificationUnreadCount}))+'">'+notificationBellIcon()+'<span class="notification-dot" id="notification-unread-dot" '+(notificationUnreadCount?'':'hidden')+'></span></button><section class="notification-panel" id="notification-panel" role="dialog" aria-label="'+esc(t('notifications.title'))+'" aria-hidden="true"><header><div><p class="eyebrow">NTC PERFORMANCE</p><h2>'+esc(t('notifications.title'))+'</h2></div><button type="button" data-notifications-read-all '+(notificationUnreadCount?'':'disabled')+'>'+esc(t('notifications.markAll'))+'</button></header><div class="notification-list" id="notification-recent-list">'+notificationPanelContent()+'</div><a class="notification-view-all" data-route href="/benachrichtigungen">'+esc(t('notifications.viewAll'))+' →</a></section></div>';}
function closeAccountMenu(restoreFocus=false){const toggle=q('[data-account-menu-toggle]'),menu=q('[data-account-menu]');accountMenuOpen=false;if(toggle)toggle.setAttribute('aria-expanded','false');if(menu){menu.classList.remove('is-open');menu.setAttribute('aria-hidden','true');}if(restoreFocus)toggle?.focus();}
function closeMainNav(restoreFocus=false){const toggle=q('[data-menu-toggle]'),nav=q('#main-nav');mainNavOpen=false;if(toggle){toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label',t('nav.openMenu'));}nav?.classList.remove('open');document.body.classList.remove('nav-open');if(restoreFocus)toggle?.focus();}
function closeHeaderMenus(){closeAccountMenu();closeMainNav();}
function accountMenuMarkup(profile,avatar){const profileHref=profilePath(profile.id),admin=profile.is_admin?'<a data-route href="/verwaltung"><span aria-hidden="true">◆</span>'+esc(t('account.admin'))+'</a>':'';return '<div class="account-menu-wrap"><button class="account-button account-menu-toggle" type="button" data-account-menu-toggle aria-haspopup="menu" aria-expanded="false"><span class="account-identity">'+avatar+'<span>'+esc(profile.name)+'</span></span><span class="account-chevron" aria-hidden="true">⌄</span></button><section class="account-menu" data-account-menu role="menu" aria-hidden="true"><div class="account-menu-heading"><strong>'+esc(profile.name)+'</strong><span>'+esc(t(profile.is_admin?'profile.admin':'profile.member'))+'</span></div><a data-route href="'+profileHref+'" role="menuitem"><span aria-hidden="true">◉</span>'+esc(t('account.profile'))+'</a><a data-route href="'+profileHref+'#profile-listings" role="menuitem"><span aria-hidden="true">▣</span>'+esc(t('account.myListings'))+'</a><a data-route href="/benachrichtigungen" role="menuitem"><span aria-hidden="true">♢</span>'+esc(t('account.notifications'))+'</a><a data-route href="/einstellungen" role="menuitem"><span aria-hidden="true">⚙</span>'+esc(t('account.settings'))+'</a>'+admin+'<button type="button" data-logout role="menuitem"><span aria-hidden="true">↗</span>'+esc(t('account.logout'))+'</button></section></div>';}
function mobileAccountMarkup(profile){if(!profile)return '<span class="mobile-nav-divider"></span><a data-route href="/anmelden">'+esc(t('account.login'))+'</a><a data-route href="/registrieren">'+esc(t('account.register'))+'</a>';const profileHref=profilePath(profile.id);return '<span class="mobile-nav-divider"></span><a data-route href="/fahrzeug-inserieren">'+esc(t('nav.create'))+'</a><a data-route href="'+profileHref+'">'+esc(t('account.profile'))+'</a><a data-route href="'+profileHref+'#profile-listings">'+esc(t('account.myListings'))+'</a><a data-route href="/benachrichtigungen">'+esc(t('account.notifications'))+'</a><a data-route href="/einstellungen">'+esc(t('account.settings'))+'</a>'+(profile.is_admin?'<a data-route href="/verwaltung">'+esc(t('account.admin'))+'</a>':'')+'<button type="button" data-logout>'+esc(t('account.logout'))+'</button>';}
function renderAccount(){const profile=user();applyAppearance(profile);applyUserPreferences(profile);I18N.apply(document);closeHeaderMenus();const avatar=profile&&profileAvatar(profile)?'<img class="account-avatar" src="'+esc(profileAvatar(profile))+'" alt="">':'<span class="account-avatar account-avatar-fallback" aria-hidden="true">◉</span>',count=REMOTE_MODE?(profile?remoteAccountCount:'–'):accounts.length;q('#account-count').textContent=count;const countLabel=q('#account-count-label');if(countLabel&&count!=='–')countLabel.textContent=plural('home.members',Number(count));q('#invite-code-field').hidden=!REMOTE_MODE;q('#account-area').innerHTML=profile?(REMOTE_MODE?notificationCenterMarkup():'')+accountMenuMarkup(profile,avatar):'<a class="account-button" data-route href="/anmelden">◯ '+esc(t('account.login'))+'</a><a class="register-button" data-route href="/registrieren">'+esc(t('account.register'))+'</a>';const mobileNav=q('#mobile-account-nav');if(mobileNav)mobileNav.innerHTML=mobileAccountMarkup(profile);updateCreateCurrency();}
function listingPath(id){return '/fahrzeuge/'+encodeURIComponent(String(id));}
function profilePath(id){return '/profil/'+encodeURIComponent(String(id));}
function safeReturnPath(value){if(!value||!String(value).startsWith('/')||String(value).startsWith('//'))return '/profil';try{const target=new URL(value,location.origin);if(target.origin!==location.origin||['/anmelden','/registrieren'].includes(target.pathname))return '/profil';return target.pathname+target.search+target.hash;}catch(error){return '/profil';}}
function authPath(mode='login',target=''){const base=mode==='register'?'/registrieren':'/anmelden';return target?base+'?return='+encodeURIComponent(safeReturnPath(target)):base;}
function postAuthPath(){return safeReturnPath(new URLSearchParams(location.search).get('return'));}
function resetAuthForms(){q('#login-form')?.reset();q('#register-form')?.reset();}
function resetPasswordForm(){q('#password-form')?.reset();}
function clearPreviewUrls(){for(const url of selectedPreviewUrls)URL.revokeObjectURL(url);selectedPreviewUrls=[];}
function updateCreateCurrency(){if(q('#create-price-currency'))q('#create-price-currency').value=I18N.currency;if(q('#create-price-label'))q('#create-price-label').textContent=t('create.price',{currency:I18N.currency});}
function resetImageSelection(){clearPreviewUrls();selectedImages=[];if(q('#images'))q('#images').value='';if(q('#file-preview'))q('#file-preview').innerHTML='';if(q('#image-count'))q('#image-count').textContent=t('create.imageLimit',{count:0,max:MAX_VEHICLE_IMAGES});}
function resetCreateDraft(){q('#create-form')?.reset();resetImageSelection();}
const VEHICLE_VALUE_KEYS={petrol:'value.petrol',benzin:'value.petrol',diesel:'value.diesel',hybrid:'value.hybrid',electric:'value.electric',elektro:'value.electric',automatic:'value.automatic',automatik:'value.automatic',manual:'value.manual',manuell:'value.manual',rwd:'value.rwd',heckantrieb:'value.rwd',awd:'value.awd',allrad:'value.awd',fwd:'value.fwd',frontantrieb:'value.fwd',new:'value.new',used:'value.used',sedan:'value.sedan',wagon:'value.wagon',coupe:'value.coupe',convertible:'value.convertible',suv:'value.suv',pickup:'value.pickup',compact:'value.compact',van:'value.van',supercar:'value.supercar',offroad:'value.offroad',solid:'value.solid',metallic:'value.metallic',matte:'value.matte',pearl:'value.pearl',cloth:'value.cloth',leather:'value.leather',alcantara:'value.alcantara',mixed:'value.mixed',fixed:'value.fixed',negotiable:'value.negotiable',available:'value.available',reserved:'value.reserved',sold:'value.sold',private:'value.privateSeller',dealer:'value.dealer',air_conditioning:'equipment.airConditioning',heated_seats:'equipment.heatedSeats',navigation:'equipment.navigation',cruise_control:'equipment.cruiseControl',rear_camera:'equipment.rearCamera',parking_sensors:'equipment.parkingSensors',led_headlights:'equipment.ledHeadlights',panoramic_roof:'equipment.panoramicRoof',tow_hitch:'equipment.towHitch',bluetooth:'equipment.bluetooth',four_wheel_steering:'equipment.fourWheelSteering'};
const VEHICLE_CANONICAL={petrol:'petrol',benzin:'petrol',diesel:'diesel',hybrid:'hybrid',electric:'electric',elektro:'electric',automatic:'automatic',automatik:'automatic',manual:'manual',manuell:'manual',rwd:'rwd',heckantrieb:'rwd',awd:'awd',allrad:'awd',fwd:'fwd',frontantrieb:'fwd'};
const BODY_TYPE_OPTIONS=['sedan','wagon','coupe','convertible','suv','pickup','compact','van','supercar','offroad'];
const EQUIPMENT_OPTIONS=['air_conditioning','heated_seats','navigation','cruise_control','rear_camera','parking_sensors','led_headlights','panoramic_roof','tow_hitch','bluetooth','four_wheel_steering'];
function vehicleValue(value){const key=VEHICLE_VALUE_KEYS[String(value||'').trim().toLocaleLowerCase('en-US')];return key?t(key):String(value||'');}
function canonicalVehicleValue(value){const normalized=String(value||'').trim().toLocaleLowerCase('en-US');return VEHICLE_CANONICAL[normalized]||normalized;}
function vehicleEditOption(value,key,current){return '<option value="'+value+'" '+(canonicalVehicleValue(current)===value?'selected':'')+'>'+esc(t(key))+'</option>';}
function optionalVehicleOptions(values,current){return '<option value="">'+esc(t('create.notSpecified'))+'</option>'+values.map(value=>'<option value="'+esc(value)+'" '+(String(current||'')===value?'selected':'')+'>'+esc(vehicleValue(value))+'</option>').join('');}
function requiredFieldLabel(text){return '<span class="field-label"><span>'+esc(text)+'</span><b class="required-marker" aria-hidden="true">*</b></span>';}
function optionalListingFields(vehicle={}){
  const selectedEquipment=Array.isArray(vehicle.equipment)?vehicle.equipment:[];
  return '<section class="listing-optional-section"><div class="listing-optional-heading"><div><p class="eyebrow">'+esc(t('create.optionalEyebrow'))+'</p><h3>'+esc(t('create.optionalHeading'))+'</h3></div></div><p class="listing-optional-intro">'+esc(t('create.optionalIntro'))+'</p><div class="form-grid optional-form-grid"><label>'+esc(t('create.condition'))+'<select name="condition">'+optionalVehicleOptions(['new','used'],vehicle.condition)+'</select></label><label>'+esc(t('create.bodyType'))+'<select name="body_type">'+optionalVehicleOptions(BODY_TYPE_OPTIONS,vehicle.body_type)+'</select></label><label>'+esc(t('create.doors'))+'<input name="doors" type="number" inputmode="numeric" min="1" max="10" value="'+esc(vehicle.doors?String(vehicle.doors):'')+'" placeholder="'+esc(t('create.optionalPlaceholder'))+'"></label><label>'+esc(t('create.seats'))+'<input name="seats" type="number" inputmode="numeric" min="1" max="100" value="'+esc(vehicle.seats?String(vehicle.seats):'')+'" placeholder="'+esc(t('create.optionalPlaceholder'))+'"></label><label>'+esc(t('create.paintFinish'))+'<select name="paint_finish">'+optionalVehicleOptions(['solid','metallic','matte','pearl'],vehicle.paint_finish)+'</select></label><label>'+esc(t('create.interiorColor'))+'<input name="interior_color" maxlength="50" value="'+esc(vehicle.interior_color||'')+'" placeholder="'+esc(t('create.optionalPlaceholder'))+'"></label><label>'+esc(t('create.interiorMaterial'))+'<select name="interior_material">'+optionalVehicleOptions(['cloth','leather','alcantara','mixed'],vehicle.interior_material)+'</select></label><label>'+esc(t('create.priceType'))+'<select name="price_type">'+optionalVehicleOptions(['fixed','negotiable'],vehicle.price_type)+'</select></label><label>'+esc(t('create.availability'))+'<select name="availability">'+optionalVehicleOptions(['available','reserved','sold'],vehicle.availability)+'</select></label><label>'+esc(t('create.sellerType'))+'<select name="seller_type">'+optionalVehicleOptions(['private','dealer'],vehicle.seller_type)+'</select></label></div><fieldset class="equipment-picker"><legend>'+esc(t('create.equipment'))+'</legend><p>'+esc(t('create.equipmentIntro'))+'</p><div class="equipment-grid">'+EQUIPMENT_OPTIONS.map(value=>'<label><input type="checkbox" name="equipment" value="'+esc(value)+'" '+(selectedEquipment.includes(value)?'checked':'')+'> <span>'+esc(vehicleValue(value))+'</span></label>').join('')+'</div></fieldset></section>';
}
function renderCreateOptionalFields(){const container=q('#create-optional-fields');if(container)container.innerHTML=optionalListingFields();}
function card(v){const image=vehicleCoverSource(v),imageCount=vehicleImageCount(v),photoStyle=image?' style="background-image:url('+esc(image)+')"':'',condition=v.condition?'<span class="card-condition">'+esc(vehicleValue(v.condition))+'</span>':'';return '<a class="listing-card" data-route href="'+listingPath(v.id)+'"><div class="card-photo"'+photoStyle+'><span class="card-category">'+esc(t('listing.category'))+'</span>'+condition+(imageCount>1?'<span class="card-gallery-count">▣ '+I18N.formatNumber(imageCount)+'</span>':'')+'</div><div class="card-body"><h3>'+esc(v.brand)+' '+esc(v.model)+'</h3><p class="card-data">'+esc(v.year)+' · '+esc(I18N.formatNumber(v.horsepower))+' '+esc(t('unit.power'))+' · '+esc(I18N.formatNumber(v.mileage))+' '+esc(t('unit.distance'))+'</p><div class="card-meta"><span class="rating">★ '+avg(v)+'</span><strong class="price">'+moneyMarkup(v.price,listingCurrency(v))+'</strong></div><span class="card-link">'+esc(t('listing.view'))+'</span></div></a>';}
function render(){if(REMOTE_MODE&&!apiSession?.token){q('#listing-count').textContent=t('listing.protected');q('#listing-grid').innerHTML='<p class="empty">'+esc(t('listing.loginHint'))+'</p>';return;}q('#listing-count').textContent=plural('listing.count',vehicles.length);q('#listing-grid').innerHTML=vehicles.length?vehicles.slice(0,6).map(card).join(''):'<p class="empty">'+esc(t('listing.none'))+'</p>';}
function catalogState(){const params=new URLSearchParams(location.search);return{q:(params.get('q')||'').trim(),condition:params.getAll('condition'),body_type:params.getAll('body_type'),fuel:params.getAll('fuel'),transmission:params.getAll('transmission'),drive:params.getAll('drive'),color:params.getAll('color'),doors:params.getAll('doors'),seats:params.getAll('seats'),price_type:params.getAll('price_type'),seller_type:params.getAll('seller_type'),availability:params.getAll('availability'),equipment:params.getAll('equipment'),price_from:params.get('price_from')||'',price_to:params.get('price_to')||'',year_from:params.get('year_from')||'',year_to:params.get('year_to')||'',mileage_from:params.get('mileage_from')||'',mileage_to:params.get('mileage_to')||'',horsepower_from:params.get('horsepower_from')||'',horsepower_to:params.get('horsepower_to')||'',sort:params.get('sort')||'newest'};}
function catalogOptions(field){const values=[...new Set(vehicles.map(vehicle=>String(vehicle[field]||'').trim()).filter(Boolean))];return values.sort((a,b)=>/^\d+$/.test(a)&&/^\d+$/.test(b)?Number(a)-Number(b):vehicleValue(a).localeCompare(vehicleValue(b),I18N.language));}
function catalogEquipmentOptions(){return [...new Set(vehicles.flatMap(vehicle=>Array.isArray(vehicle.equipment)?vehicle.equipment:[]).filter(Boolean))].sort((a,b)=>vehicleValue(a).localeCompare(vehicleValue(b),I18N.language));}
function comparablePrice(vehicle){const value=I18N.currencyValue(Number(vehicle.price)||0,listingCurrency(vehicle));return value.currency===I18N.currency?value.amount:null;}
function numericBound(value){if(value===''||value===null||value===undefined)return null;const number=Number(value);return Number.isFinite(number)?number:null;}
function matchesRange(value,from,to){const minimum=numericBound(from),maximum=numericBound(to),number=Number(value);if(!Number.isFinite(number))return minimum===null&&maximum===null;if(minimum!==null&&number<minimum)return false;if(maximum!==null&&number>maximum)return false;return true;}
function vehicleRatingValue(vehicle){if(Number.isFinite(Number(vehicle.rating_average)))return Number(vehicle.rating_average);const count=Number(vehicle.rating_count)||0;return count?(Number(vehicle.rating_sum)||0)/count:0;}
function sortCatalog(list,sort){const sorted=list.slice();if(sort==='price_asc')return sorted.sort((a,b)=>(comparablePrice(a)??Number.MAX_SAFE_INTEGER)-(comparablePrice(b)??Number.MAX_SAFE_INTEGER));if(sort==='price_desc')return sorted.sort((a,b)=>(comparablePrice(b)??-1)-(comparablePrice(a)??-1));if(sort==='mileage_asc')return sorted.sort((a,b)=>(Number(a.mileage)||0)-(Number(b.mileage)||0));if(sort==='horsepower_desc')return sorted.sort((a,b)=>(Number(b.horsepower)||0)-(Number(a.horsepower)||0));if(sort==='year_desc')return sorted.sort((a,b)=>(Number(b.year)||0)-(Number(a.year)||0));if(sort==='rating_desc')return sorted.sort((a,b)=>vehicleRatingValue(b)-vehicleRatingValue(a));return sorted.sort((a,b)=>{const aTime=Date.parse(a.created_at||''),bTime=Date.parse(b.created_at||'');return Number.isFinite(aTime)&&Number.isFinite(bTime)?bTime-aTime:0;});}
function filterCatalog(state){const query=state.q.toLocaleLowerCase(I18N.language),exactFields=['condition','body_type','fuel','transmission','drive','color','price_type','seller_type','availability'];const filtered=vehicles.filter(vehicle=>{const equipment=Array.isArray(vehicle.equipment)?vehicle.equipment:[],haystack=[vehicle.brand,vehicle.model,vehicle.location,vehicle.fuel,vehicleValue(vehicle.fuel),vehicle.transmission,vehicleValue(vehicle.transmission),vehicle.drive,vehicleValue(vehicle.drive),vehicle.color,vehicle.condition,vehicleValue(vehicle.condition),vehicle.body_type,vehicleValue(vehicle.body_type),vehicle.interior_color,vehicle.interior_material,vehicleValue(vehicle.interior_material),...equipment,...equipment.map(vehicleValue)].join(' ').toLocaleLowerCase(I18N.language);if(query&&!haystack.includes(query))return false;for(const field of exactFields)if(state[field].length&&!state[field].includes(String(vehicle[field]||'')))return false;if(state.doors.length&&!state.doors.includes(String(vehicle.doors||'')))return false;if(state.seats.length&&!state.seats.includes(String(vehicle.seats||'')))return false;if(state.equipment.length&&!state.equipment.every(value=>equipment.includes(value)))return false;const price=comparablePrice(vehicle),priceRangeActive=state.price_from!==''||state.price_to!=='';if(priceRangeActive&&(price===null||!matchesRange(price,state.price_from,state.price_to)))return false;if(!matchesRange(vehicle.year,state.year_from,state.year_to))return false;if(!matchesRange(vehicle.mileage,state.mileage_from,state.mileage_to))return false;if(!matchesRange(vehicle.horsepower,state.horsepower_from,state.horsepower_to))return false;return true;});return sortCatalog(filtered,state.sort);}
function filterChecks(name,labelKey,values,selected){if(!values.length)return'';return '<fieldset><legend>'+esc(t(labelKey))+'</legend><div class="filter-checks">'+values.map(value=>'<label><input type="checkbox" name="'+name+'" value="'+esc(value)+'" '+(selected.includes(String(value))?'checked':'')+'> '+esc(vehicleValue(value))+'</label>').join('')+'</div></fieldset>';}
function rangeFilter(labelKey,fromName,toName,state,minimum,maximum,unit=''){return '<fieldset class="filter-range"><legend>'+esc(t(labelKey))+'</legend><div class="filter-range-row"><input name="'+fromName+'" type="number" inputmode="numeric" min="'+minimum+'" max="'+maximum+'" value="'+esc(state[fromName])+'" placeholder="'+esc(t('catalog.fromInput'))+'" aria-label="'+esc(t('catalog.rangeFromAria',{label:t(labelKey)}))+'"><span aria-hidden="true">–</span><input name="'+toName+'" type="number" inputmode="numeric" min="'+minimum+'" max="'+maximum+'" value="'+esc(state[toName])+'" placeholder="'+esc(t('catalog.toInput'))+'" aria-label="'+esc(t('catalog.rangeToAria',{label:t(labelKey)}))+'">'+(unit?'<small>'+esc(unit)+'</small>':'')+'</div></fieldset>';}
function sortOptions(current){const options=[['newest','catalog.sortNewest'],['price_asc','catalog.sortPriceAsc'],['price_desc','catalog.sortPriceDesc'],['mileage_asc','catalog.sortMileage'],['horsepower_desc','catalog.sortPower'],['year_desc','catalog.sortYear'],['rating_desc','catalog.sortRating']];return options.map(([value,key])=>'<option value="'+value+'" '+(current===value?'selected':'')+'>'+esc(t(key))+'</option>').join('');}
function vehicleCatalogMarkup(){const state=catalogState(),list=filterCatalog(state),rangeCount=[['price_from','price_to'],['year_from','year_to'],['mileage_from','mileage_to'],['horsepower_from','horsepower_to']].filter(([from,to])=>state[from]!==''||state[to]!=='').length,filterCount=state.condition.length+state.body_type.length+state.fuel.length+state.transmission.length+state.drive.length+state.color.length+state.doors.length+state.seats.length+state.price_type.length+state.seller_type.length+state.availability.length+state.equipment.length+rangeCount;return '<div class="route-shell catalog-page"><a class="route-back" data-route href="/#home">← '+esc(t('common.backHome'))+'</a><header class="catalog-heading"><div><p class="eyebrow">'+esc(t('catalog.eyebrow'))+'</p><h1>'+esc(t('catalog.headingLead'))+' <em>'+esc(t('catalog.headingAccent'))+'</em></h1><p>'+esc(t('catalog.intro'))+'</p></div><strong>'+esc(plural('catalog.result',list.length))+'</strong></header><form class="catalog-search" id="catalog-search-form"><span aria-hidden="true">⌕</span><input name="q" type="search" aria-label="'+esc(t('catalog.searchAria'))+'" value="'+esc(state.q)+'" placeholder="'+esc(t('catalog.searchPlaceholder'))+'"><button class="btn btn-primary">'+esc(t('common.search'))+'</button></form><details class="catalog-filter-menu" '+(filterCount?'open':'')+'><summary>'+esc(t('catalog.filters'))+' <span>'+(filterCount?esc(plural('catalog.filterActive',filterCount)):esc(t('catalog.allFilters')))+'</span></summary><form id="catalog-filter-form"><input type="hidden" name="q" value="'+esc(state.q)+'"><section class="catalog-filter-group catalog-filter-primary"><h2>'+esc(t('catalog.vehicleBasics'))+'</h2><div class="catalog-filter-grid">'+filterChecks('condition','catalog.condition',['new','used'],state.condition)+filterChecks('body_type','catalog.bodyType',BODY_TYPE_OPTIONS,state.body_type)+filterChecks('fuel','catalog.fuel',catalogOptions('fuel'),state.fuel)+filterChecks('transmission','catalog.transmission',catalogOptions('transmission'),state.transmission)+filterChecks('drive','catalog.drive',catalogOptions('drive'),state.drive)+'</div></section><section class="catalog-filter-group"><h2>'+esc(t('catalog.customRanges'))+'</h2><div class="catalog-range-grid">'+rangeFilter('catalog.priceRange','price_from','price_to',state,0,100000000,I18N.currency)+rangeFilter('catalog.modelYear','year_from','year_to',state,1900,2100)+rangeFilter('catalog.mileageRange','mileage_from','mileage_to',state,0,2000000,t('unit.distance'))+rangeFilter('catalog.powerRange','horsepower_from','horsepower_to',state,1,5000,t('unit.power'))+'</div></section><section class="catalog-filter-group"><h2>'+esc(t('catalog.moreFilters'))+'</h2><div class="catalog-filter-grid">'+filterChecks('color','catalog.color',catalogOptions('color'),state.color)+filterChecks('doors','catalog.doors',catalogOptions('doors'),state.doors)+filterChecks('seats','catalog.seats',catalogOptions('seats'),state.seats)+filterChecks('price_type','catalog.priceType',['fixed','negotiable'],state.price_type)+filterChecks('seller_type','catalog.sellerType',['private','dealer'],state.seller_type)+filterChecks('availability','catalog.availability',['available','reserved','sold'],state.availability)+filterChecks('equipment','catalog.equipment',catalogEquipmentOptions(),state.equipment)+'</div></section><label class="catalog-sort">'+esc(t('catalog.sort'))+'<select name="sort">'+sortOptions(state.sort)+'</select></label><div class="catalog-filter-actions"><button class="btn btn-primary">'+esc(t('catalog.apply'))+'</button><button class="btn btn-outline" type="button" data-clear-catalog>'+esc(t('catalog.reset'))+'</button></div></form></details><section class="catalog-results"><div class="listing-grid">'+(list.length?list.map(card).join(''):'<div class="empty catalog-empty"><strong>'+esc(t('catalog.none'))+'</strong><span>'+esc(t('catalog.noneHint'))+'</span><button class="btn btn-outline" type="button" data-clear-catalog>'+esc(t('catalog.clear'))+'</button></div>')+'</div></section></div>';}
function pathFromCatalogForm(form){const params=new URLSearchParams();for(const [name,value] of new FormData(form).entries()){const normalized=String(value).trim();if(normalized)params.append(name,normalized);}const query=params.toString();return '/fahrzeuge'+(query?'?'+query:'');}
