  if(e.target.closest('[data-notifications-read-all]')){await markAllNotificationsRead();return;}
  if(e.target.closest('[data-notifications-retry]')){loadRecentNotifications();return;}
  if(e.target.closest('[data-notification-history-retry]')){loadNotificationHistory(true);return;}
  if(e.target.closest('[data-notification-load-more]')){loadNotificationHistory(false);return;}
  const route=e.target.closest('a[data-route]');if(route&&e.button===0&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey){e.preventDefault();closeHeaderMenus();navigate(route.getAttribute('href'));return;}
  if(e.target.closest('[data-close]')){close();return;}
  if(e.target.closest('[data-clear-catalog]')){navigate('/fahrzeuge');return;}
  if(e.target.closest('.create-trigger')){navigate(user()?'/fahrzeug-inserieren':authPath('login','/fahrzeug-inserieren'));return;}
  const ac=e.target.closest('[data-account]');if(ac){navigate(ac.dataset.mode==='register'?'/registrieren':'/anmelden');return;}
  if(e.target.closest('[data-logout]')){closeHeaderMenus();if(REMOTE_MODE&&apiSession?.token){try{await api('logout',{method:'POST'});}catch(error){/* Always clear the local bearer token, even if the NAS is temporarily unavailable. */}}clearRemoteSession();close();renderAccount();render();navigate('/#home',true);toast.info(t('toast.loggedOut'));return;}
  const imageMenu=e.target.closest('[data-image-menu]');if(imageMenu){const open=imageMenu.getAttribute('aria-expanded')==='true';closeImageMenus(imageMenu);imageMenu.setAttribute('aria-expanded',String(!open));const menu=imageMenu.parentElement?.querySelector('.edit-image-menu');if(menu)menu.hidden=open;return;}
