document.addEventListener('submit',async e=>{
  if(e.target.id==='rating-message-form'){e.preventDefault();await sendRatingMessage(e.target);return;}
  if(e.target.id==='catalog-search-form'){e.preventDefault();const params=new URLSearchParams(location.search),query=new FormData(e.target).get('q').trim();if(query)params.set('q',query);else params.delete('q');navigate('/fahrzeuge'+(params.toString()?'?'+params.toString():''));return;}
  if(e.target.id==='catalog-filter-form'){e.preventDefault();if(validateCatalogRanges(e.target))navigate(pathFromCatalogForm(e.target));return;}
  if(e.target.id==='edit-listing-form'){e.preventDefault();const button=e.submitter;if(button.disabled)return;const listingId=e.target.dataset.listingId,vehicle=vehicles.find(item=>String(item.id)===String(listingId));if(!vehicle||String(vehicle.owner_id)!==String(user()?.id)){toast.warning(t('edit.permissionText'));return;}const form=new FormData(e.target),files=[...e.target.querySelector('[name="images[]"]').files],currentCount=vehicleImageCount(vehicle);if(currentCount+files.length>MAX_VEHICLE_IMAGES){toast.warning(t('toast.imageCountRemaining',{remaining:Math.max(0,MAX_VEHICLE_IMAGES-currentCount),max:MAX_VEHICLE_IMAGES}));return;}if(files.some(file=>file.size>5*1024*1024)){toast.warning(t('toast.imageTooLarge'));return;}button.disabled=true;try{if(REMOTE_MODE){await api('update_listing',{method:'POST',body:form});await refreshRemote(true);}else{vehicle.equipment=form.getAll('equipment').map(value=>String(value));for(const [key,value] of form.entries()){if(key==='listing_id'||key==='images[]'||key==='equipment')continue;vehicle[key]=['year','price','mileage','horsepower','doors','seats'].includes(key)?Number(value):value;}if(files.length){const appended=await Promise.all(files.map(file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);})));vehicle.images.push(...appended);}save();render();}navigate(listingPath(listingId),true);toast.success(t('toast.vehicleUpdated'));}catch(error){if(unavailable(error))serverStatus(false);toast.error(error.message);}finally{button.disabled=false;}return;}
  if(e.target.id==='admin-ban-form'){e.preventDefault();const button=e.submitter;if(button.disabled)return;button.disabled=true;const form=new FormData(e.target),duration=Number(form.get('duration_days')),durationLabel=duration?plural('admin.day',duration):t('admin.permanentOption'),name=e.target.dataset.userName||t('common.unknown');await confirmAction({tone:'danger',title:t('dialog.adminBanTitle'),message:t('dialog.adminBanMessage',{name,duration:durationLabel}),detail:t('dialog.adminLogged'),confirmLabel:t('dialog.adminBanConfirm')},async()=>{await api('admin_ban_user',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({user_id:Number(e.target.dataset.userId),duration_days:duration,reason:String(form.get('reason')).trim()})});toast.success(t('toast.suspensionSaved'));navigate('/verwaltung',true);});button.disabled=false;return;}
  if(e.target.id==='admin-delete-form'){e.preventDefault();const button=e.submitter;if(button.disabled)return;const form=new FormData(e.target),rawDate=String(form.get('effective_at')),effectiveDate=new Date(rawDate);if(Number.isNaN(effectiveDate.getTime())){toast.error(t('toast.invalidActionDate'));return;}button.disabled=true;await confirmAction({tone:'danger',title:t('dialog.adminDeleteTitle'),message:t('dialog.adminDeleteMessage',{vehicle:e.target.dataset.vehicleName||t('common.unknown')}),detail:t('dialog.adminDeleteDetail'),confirmLabel:t('dialog.adminDeleteConfirm')},async()=>{await api('admin_delete_listing',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({listing_id:Number(e.target.dataset.listingId),reason:String(form.get('reason')).trim(),effective_at:effectiveDate.toISOString()})});await refreshRemote(true);navigate('/fahrzeuge');toast.success(t('toast.adminDeleted'));});button.disabled=false;}
});
q('#login-form').addEventListener('submit',e=>{e.preventDefault();const destination=postAuthPath(),f=new FormData(e.target),mail=f.get('email').trim().toLowerCase(),found=accounts.find(a=>a.email===mail&&a.password===f.get('password'));if(!found){toast.error(t('error.emailPassword'));return;}sessionId=found.id;localStorage.setItem(KEYS.session,found.id);resetAuthForms();renderAccount();close();navigate(destination,true);toast.success(t('toast.welcomeBack',{name:found.name}));});
q('#register-form').addEventListener('submit',e=>{e.preventDefault();const destination=postAuthPath(),f=new FormData(e.target),mail=f.get('email').trim().toLowerCase();if(accounts.some(a=>a.email===mail)){toast.error(t('error.emailExists'));return;}const stamp=new Date().toISOString(),u={id:'user-'+Date.now(),name:f.get('name').trim(),email:mail,password:f.get('password'),bio:'',avatar_url:'',profile_visibility:'public',appearance:'oled-blue',language:I18N.language,currency:I18N.currency,notify_listings:true,notify_messages:true,created_at:stamp,updated_at:stamp};accounts.push(u);sessionId=u.id;localStorage.setItem(KEYS.session,u.id);save();resetAuthForms();renderAccount();close();navigate(destination,true);toast.success(t('toast.welcome',{name:u.name}));});
q('#images').addEventListener('change',e=>{const files=[...e.target.files];clearPreviewUrls();if(files.length>MAX_VEHICLE_IMAGES){resetImageSelection();toast.warning(t('toast.imageCount',{max:MAX_VEHICLE_IMAGES}));return;}if(files.some(f=>f.size>5*1024*1024)){resetImageSelection();toast.warning(t('toast.imageTooLarge'));return;}selectedImages=files;selectedPreviewUrls=files.map(file=>URL.createObjectURL(file));q('#image-count').textContent=t('create.imageLimit',{count:I18N.formatNumber(files.length),max:MAX_VEHICLE_IMAGES});q('#file-preview').innerHTML=selectedPreviewUrls.map(url=>'<img src="'+url+'" loading="lazy" decoding="async" alt="'+esc(t('create.images'))+'"/>').join('');});
document.addEventListener('change',e=>{if(e.target.id!=='edit-images-input')return;const files=[...e.target.files],hint=q('#edit-images-hint'),vehicle=active,current=vehicleImageCount(vehicle),remaining=Math.max(0,MAX_VEHICLE_IMAGES-current),total=current+files.length;if(files.length>remaining){e.target.value='';toast.warning(t('toast.imageCountRemaining',{remaining:I18N.formatNumber(remaining),max:MAX_VEHICLE_IMAGES}));if(hint)hint.textContent=t('edit.keepImages',{current:I18N.formatNumber(current),remaining:I18N.formatNumber(remaining),max:MAX_VEHICLE_IMAGES});return;}if(files.some(file=>file.size>5*1024*1024)){e.target.value='';toast.warning(t('toast.imageTooLarge'));if(hint)hint.textContent=t('edit.keepImages',{current:I18N.formatNumber(current),remaining:I18N.formatNumber(remaining),max:MAX_VEHICLE_IMAGES});return;}if(hint)hint.textContent=files.length?t('edit.replaceCount',{count:I18N.formatNumber(files.length),total:I18N.formatNumber(total),max:MAX_VEHICLE_IMAGES}):t('edit.keepImages',{current:I18N.formatNumber(current),remaining:I18N.formatNumber(remaining),max:MAX_VEHICLE_IMAGES});});
q('#create-form').addEventListener('submit',async e=>{e.preventDefault();if(!user()){navigate(authPath('login','/fahrzeug-inserieren'));return;}if(!selectedImages.length){toast.warning(t('toast.imageRequired'));return;}updateCreateCurrency();const b=e.submitter;b.disabled=true;try{if(REMOTE_MODE){await api('create_listing',{method:'POST',body:new FormData(e.target)});await refreshRemote(true);}else{const images=await Promise.all(selectedImages.map(f=>new Promise(ok=>{const r=new FileReader();r.onload=()=>ok(r.result);r.readAsDataURL(f);})));const f=new FormData(e.target),v={id:'vehicle-'+Date.now(),owner_id:user().id,seller:user().name,images,rating_sum:0,rating_count:0,ratings:{},comments:[],equipment:f.getAll('equipment').map(value=>String(value))};for(const pair of f.entries()){if(pair[0]==='equipment')continue;v[pair[0]]=['year','price','mileage','horsepower','doors','seats'].includes(pair[0])?Number(pair[1]):pair[1];}vehicles.unshift(v);save();render();}resetCreateDraft();close();navigate('/fahrzeuge');toast.success(t('toast.vehiclePublished'));}catch(error){if(unavailable(error))serverStatus(false);toast.error(error.message);}finally{b.disabled=false;}});
q('#rating-comment').addEventListener('input',e=>q('#rating-counter').textContent=I18N.formatNumber(e.target.value.length)+' / 500');
document.addEventListener('input',e=>{if(e.target.id==='rating-message-body'){const counter=e.target.closest('form')?.querySelector('small');if(counter)counter.textContent=I18N.formatNumber(e.target.value.length)+' / 1000';}});
q('#save-rating').addEventListener('click',async()=>{if(!active){close();toast.warning(t('toast.listingClosed'));return;}if(!pickedRating){toast.warning(t('toast.ratingMissing'));return;}const button=q('#save-rating');button.disabled=true;try{if(REMOTE_MODE){await api('rate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({listing_id:Number(active.id),score:pickedRating,comment:q('#rating-comment').value})});await refreshRemote(true);}else{const old=currentRating(active);if(old)active.rating_sum-=old.score;else active.rating_count++;active.rating_sum+=pickedRating;active.ratings[user().id]={score:pickedRating,comment:q('#rating-comment').value,updated_at:new Date().toISOString(),messages:Array.isArray(old?.messages)?old.messages:[]};save();render();renderRoute();}close();q('#success-text').textContent=t('rating.success',{count:I18N.formatNumber(pickedRating)});modal('#success-modal');}catch(error){if(unavailable(error))serverStatus(false);toast.error(error.message);}finally{button.disabled=false;}});
document.addEventListener('submit',async e=>{if(e.target.id!=='comment-form')return;e.preventDefault();const b=e.submitter;if(b.disabled)return;b.disabled=true;const body=e.target.querySelector('textarea').value.trim();try{if(body&&REMOTE_MODE){const requestId=window.crypto&&crypto.randomUUID?crypto.randomUUID():'comment-'+Date.now()+'-'+Math.random().toString(16).slice(2);const listingId=Number(active.id);await api('comment',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({listing_id:listingId,body,request_id:requestId})});await refreshRemote(true);}else if(body){active.comments.unshift({id:'comment-'+Date.now(),user_name:user().name,body});save();renderRoute();}}catch(error){if(unavailable(error))serverStatus(false);toast.error(error.message);}finally{b.disabled=false;}});
async function deleteVehicle(){if(!active)return;const listingId=active.id,vehicleName=active.brand+' '+active.model;await confirmAction({tone:'danger',title:t('dialog.deleteVehicleTitle'),message:t('dialog.deleteVehicleMessage',{vehicle:vehicleName}),detail:t('dialog.deleteVehicleDetail'),confirmLabel:t('dialog.deleteVehicleConfirm')},async()=>{try{if(REMOTE_MODE){await api('delete_listing',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({listing_id:Number(listingId)})});await refreshRemote(true);}else{vehicles=vehicles.filter(v=>String(v.id)!==String(listingId));if(!save())throw new Error(t('toast.storageFull'));render();}navigate('/fahrzeuge');toast.success(t('toast.vehicleDeleted'));}catch(error){if(unavailable(error))serverStatus(false);throw error;}});}
function revokeProtectedUrl(url){if(url&&protectedObjectUrls.has(url)){URL.revokeObjectURL(url);protectedObjectUrls.delete(url);}}
function revokeProtectedUrls(urls){for(const url of urls)revokeProtectedUrl(url);}
function dropCachedProfile(id){const cached=publicProfileCache.get(String(id));revokeProtectedUrl(cached?.avatar_object_url);publicProfileCache.delete(String(id));}
function clearPublicProfileCache(){for(const id of [...publicProfileCache.keys()])dropCachedProfile(id);publicProfileRequests.clear();}
function clearProtectedMedia(){revokeProtectedUrls([...protectedObjectUrls]);clearPublicProfileCache();}
function persistRemoteSession(){if(!apiSession)return;const stored={...apiSession,user:{...(apiSession.user||{})}};delete stored.user.avatar_object_url;localStorage.setItem(API_SESSION_KEY,JSON.stringify(stored));}
function clearRemoteSession(){clearProtectedMedia();resetAuthForms();resetPasswordForm();resetCreateDraft();resetNotificationState();apiSession=null;sessionId=null;active=null;remoteAccountCount=0;remoteListingsReady=true;if(REMOTE_MODE)vehicles=[];localStorage.removeItem(KEYS.session);localStorage.removeItem(API_SESSION_KEY);}
async function protectedMedia(url){
  if(!apiSession?.token)throw new Error(t('error.signIn'));
  if(protectedMediaLoads.has(url))return protectedMediaLoads.get(url);
  const request=(async()=>{let response;try{response=await fetch(url,{headers:{Authorization:'Bearer '+apiSession.token,'Accept-Language':I18N.language},cache:'no-store'});}catch(error){throw new Error(t('error.connectImage'));}if(!response.ok){let message=t('error.protectedImage');try{const data=await response.json();message=data.error||message;}catch(error){}throw new Error(message);}const objectUrl=URL.createObjectURL(await response.blob());protectedObjectUrls.add(objectUrl);return objectUrl;})().finally(()=>protectedMediaLoads.delete(url));
  protectedMediaLoads.set(url,request);return request;
}
async function hydrateProfile(profile,cachedProfile=null){if(profile&&REMOTE_MODE){profile.avatar_object_url='';if(profile.avatar_url&&cachedProfile?.avatar_url===profile.avatar_url&&cachedProfile.avatar_object_url)profile.avatar_object_url=cachedProfile.avatar_object_url;else if(profile.avatar_url){try{profile.avatar_object_url=await protectedMedia(profile.avatar_url);}catch(error){profile.avatar_load_failed=true;}}}return profile;}
async function asyncPool(values,limit,worker){const results=new Array(values.length);let next=0;async function run(){while(next<values.length){const index=next++;results[index]=await worker(values[index],index);}}await Promise.all(Array.from({length:Math.min(limit,values.length)},run));return results;}
async function hydrateVehicles(items,cachedItems=[],onPrimaryReady=null){const mediaCache=new Map(),resolvedMedia=new Map();for(const vehicle of cachedItems){const sources=Array.isArray(vehicle.image_urls)?vehicle.image_urls:[],objects=Array.isArray(vehicle.image_object_urls)?vehicle.image_object_urls:[];sources.forEach((url,index)=>{if(url&&objects[index]){resolvedMedia.set(url,objects[index]);mediaCache.set(url,Promise.resolve(objects[index]));}});if(vehicle.seller_avatar_url&&vehicle.seller_avatar_object_url){resolvedMedia.set(vehicle.seller_avatar_url,vehicle.seller_avatar_object_url);mediaCache.set(vehicle.seller_avatar_url,Promise.resolve(vehicle.seller_avatar_object_url));}}const load=url=>{if(!url)return Promise.resolve('');if(!mediaCache.has(url))mediaCache.set(url,protectedMedia(url).catch(() =>''));return mediaCache.get(url);};await asyncPool(items,2,async vehicle=>{vehicle.image_object_urls=vehicle.image_urls.map(url=>resolvedMedia.get(url)||'');const coverIndex=vehicleCoverIndex(vehicle);if(vehicle.image_urls[coverIndex]&&!vehicle.image_object_urls[coverIndex])vehicle.image_object_urls[coverIndex]=await load(vehicle.image_urls[coverIndex]);vehicle.images=vehicle.image_object_urls.filter(Boolean);vehicle.gallery_hydrated=vehicle.image_urls.every((url,index)=>!url||Boolean(vehicle.image_object_urls[index]));});if(onPrimaryReady)onPrimaryReady(items);await asyncPool(items,2,async vehicle=>{vehicle.seller_avatar_object_url=await load(vehicle.seller_avatar_url);if(vehicle.seller_avatar_url&&!vehicle.seller_avatar_object_url)vehicle.seller_avatar_load_failed=true;});return items;}
async function hydrateVehicleGallery(vehicle){if(!REMOTE_MODE||!vehicle?.image_urls?.length||vehicle.gallery_hydrated)return vehicle;const key=String(vehicle.id);if(vehicleGalleryLoads.has(key))return vehicleGalleryLoads.get(key);const request=(async()=>{const sources=vehicle.image_urls,objects=Array.isArray(vehicle.image_object_urls)?vehicle.image_object_urls.slice(0,sources.length):new Array(sources.length).fill('');while(objects.length<sources.length)objects.push('');const missing=sources.map((url,index)=>url&&!objects[index]?index:-1).filter(index=>index>=0);await asyncPool(missing,2,async index=>{try{objects[index]=await protectedMedia(sources[index]);}catch(error){objects[index]='';}});vehicle.image_object_urls=objects;vehicle.images=objects.filter(Boolean);vehicle.gallery_hydrated=true;return vehicle;})().finally(()=>vehicleGalleryLoads.delete(key));vehicleGalleryLoads.set(key,request);return request;}
function loadRouteVehicleGallery(vehicle){if(!REMOTE_MODE||vehicle.gallery_hydrated)return;hydrateVehicleGallery(vehicle).then(()=>{const path=location.pathname.replace(/\/+$/,'')||'/';if(active===vehicle&&/^\/fahrzeuge\/[^/]+(?:\/bearbeiten)?$/.test(path))renderRoute();}).catch(()=>{});}
function hydratedMediaUrls(items,profile){const used=new Set();for(const vehicle of items){for(const url of vehicle.image_object_urls||[])if(url)used.add(url);if(vehicle.seller_avatar_object_url)used.add(vehicle.seller_avatar_object_url);}if(profile?.avatar_object_url)used.add(profile.avatar_object_url);return used;}
function replaceRemoteProfile(profile){const previous=apiSession?.user?.avatar_object_url;if(previous&&previous!==profile?.avatar_object_url)revokeProtectedUrl(previous);apiSession.user=profile;persistRemoteSession();}
async function api(action,options={}){
  if(!REMOTE_MODE)throw new Error(t('error.serverSetup'));
  const request={...options},query=request.query||{},headers={'Accept-Language':I18N.language,...(request.headers||{})};delete request.query;if(apiSession?.token)headers.Authorization='Bearer '+apiSession.token;const params=new URLSearchParams({action});for(const [name,value] of Object.entries(query))if(value!==undefined&&value!==null)params.set(name,String(value));
  let response;try{response=await fetch(API+'?'+params.toString(),{...request,headers});}catch(error){throw new Error(t('error.connectServer'));}
  const raw=await response.text();let data={};try{data=raw?JSON.parse(raw):{};}catch(error){if(response.status===503)throw new Error(t('error.maintenance'));if(response.status>=500)throw new Error(t('error.invalidServer'));throw new Error(t('error.invalidResponse'));}
  if(!response.ok){if(response.status===503)throw new Error(data.error||t('error.maintenance'));if(response.status>=500){const message=data.error||t('error.internalServer');throw new Error(/^NTC-/.test(message)?message:'NTC-SERVER-502 · '+message);}const error=new Error(data.error||'NTC-HTTP-'+response.status+' · '+t('error.http'));error.status=response.status;error.code=data.error_code||(data.banned?'ACCOUNT_BANNED':'NTC_HTTP_'+response.status);error.details=data;throw error;}return data;
}
async function refreshRemote(silent=false){
  if(!REMOTE_MODE)return;
  if(!apiSession?.token){clearProtectedMedia();vehicles=[];remoteAccountCount=0;remoteListingsReady=true;serverStatus(true);render();renderAccount();renderRoute();return null;}
  const previousUrls=new Set(protectedObjectUrls),cachedVehicles=vehicles,cachedProfile=apiSession.user;
  let data;
  try{
    data=await api('bootstrap');
    const nextVehicles=(data.vehicles||[]).map(normalizeRemoteVehicle);
    if(!data.profile||typeof data.profile!=='object')throw new Error(t('error.profileInvalid'));
    const nextProfile={...data.profile};
    if(nextProfile.avatar_url&&cachedProfile?.avatar_url===nextProfile.avatar_url&&cachedProfile.avatar_object_url)nextProfile.avatar_object_url=cachedProfile.avatar_object_url;

    // Publish the small JSON payload immediately. Protected vehicle images can
    // be several megabytes and must never block counts, cards or route data on
    // slower mobile connections.
    clearPublicProfileCache();
    vehicles=nextVehicles;
    apiSession.user=nextProfile;
    remoteAccountCount=Number(data.account_count)||0;
    remoteListingsReady=true;
    applyUserPreferences(nextProfile);
    persistRemoteSession();
    serverStatus(true);
    render();renderAccount();renderRoute();

    const [hydratedVehicles,hydratedProfile]=await Promise.all([
      hydrateVehicles(nextVehicles,cachedVehicles,()=>{render();const path=location.pathname.replace(/\/+$/,'')||'/';if(path==='/fahrzeuge'||/^\/fahrzeuge\/[^/]+$/.test(path))renderRoute();}),
      hydrateProfile(nextProfile,cachedProfile)
    ]),usedUrls=hydratedMediaUrls(hydratedVehicles,hydratedProfile);
    revokeProtectedUrls([...previousUrls].filter(url=>!usedUrls.has(url)));
    vehicles=hydratedVehicles;
    apiSession.user=hydratedProfile;
    persistRemoteSession();
  }catch(error){for(const url of [...protectedObjectUrls])if(!previousUrls.has(url))revokeProtectedUrl(url);if(error.code==='ACCOUNT_BANNED'||error.status===401){const banned=error.code==='ACCOUNT_BANNED';clearRemoteSession();render();renderAccount();renderRoute();if(!silent)toast.error(banned?error.message:t('error.sessionExpired'));return null;}remoteListingsReady=true;if(unavailable(error))serverStatus(false);render();renderAccount();renderRoute();if(!silent)toast.error(unavailable(error)?error.message:t('error.protectedData'));throw error;}
  render();renderAccount();renderRoute();return data;
}
function ensureLocalProfile(){const u=user();if(!u)return null;u.bio=u.bio||'';u.profile_visibility=u.profile_visibility||'public';u.appearance=u.appearance||'oled-blue';u.language=I18N.SUPPORTED_LANGUAGES.includes(u.language)?u.language:I18N.DEFAULT_LANGUAGE;u.currency=I18N.SUPPORTED_CURRENCIES.includes(u.currency)?u.currency:I18N.DEFAULT_CURRENCY;u.notify_listings=u.notify_listings!==false;u.notify_messages=u.notify_messages!==false;return u;}
function profileAvatar(profile){return REMOTE_MODE?(profile.avatar_object_url||''):(profile.avatar_url||'');}
function updateOwnerProfile(profile){if(!profile)return;dropCachedProfile(profile.id);for(const vehicle of vehicles){if(String(vehicle.owner_id)!==String(profile.id))continue;const nextAvatar=profileAvatar(profile);if(vehicle.seller_avatar_object_url&&vehicle.seller_avatar_object_url!==nextAvatar)revokeProtectedUrl(vehicle.seller_avatar_object_url);vehicle.seller=profile.name||vehicle.seller;vehicle.seller_available=true;vehicle.seller_avatar_object_url=nextAvatar;}}
document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="settings-modal"><div class="modal-backdrop" data-close></div><section class="modal-panel settings-panel"><button class="close-modal" data-close>×</button><p class="eyebrow" data-i18n="settings.eyebrow">NTC PERFORMANCE ACCOUNT</p><h2><span data-i18n="settings.headingLead">Profile &amp;</span> <em data-i18n="settings.headingAccent">settings.</em></h2><div class="settings-profile"><div class="avatar-preview" id="avatar-preview">◉</div><div><label class="avatar-label"><span data-i18n="settings.avatar">Profile picture</span> <input id="avatar-input" type="file" accept="image/jpeg,image/png,image/webp"></label><small id="avatar-hint" data-i18n="${REMOTE_MODE?'settings.avatarRemote':'settings.avatarLocal'}"></small><button type="button" class="link-button" id="delete-avatar" data-i18n="settings.removeImage">Remove image</button></div></div><form id="settings-form"><label><span data-i18n="settings.displayName">Display name</span><input id="settings-name" maxlength="40" required></label><label><span data-i18n="settings.bio">Bio</span> <span id="bio-count">0 / 280</span><textarea id="settings-bio" maxlength="280" rows="3" data-i18n-placeholder="settings.bioPlaceholder"></textarea></label><label><span data-i18n="settings.email">Email address</span><input id="settings-email" type="email" readonly><small data-i18n="settings.emailHint"></small></label><div class="settings-grid"><label><span data-i18n="settings.visibility">Profile visibility</span><select id="settings-visibility"><option value="public" data-i18n="settings.public">Public</option><option value="private" data-i18n="settings.private">Private</option></select></label><label><span data-i18n="settings.language">Language</span><select id="settings-language"><option value="en-US" data-i18n="settings.english">English (US)</option><option value="de-DE" data-i18n="settings.german">German</option></select></label><label><span data-i18n="settings.currency">Currency</span><select id="settings-currency"><option value="USD" data-i18n="settings.usd">US Dollar ($)</option><option value="EUR" data-i18n="settings.eur">Euro (€)</option></select><small data-i18n="settings.currencyHint"></small></label></div><fieldset class="accent-picker"><legend data-i18n="settings.accent">Accent color</legend><div class="accent-swatches" id="accent-swatches" role="radiogroup" data-i18n-aria-label="settings.accentAria">${accentSwatches()}</div><div class="custom-accent-row"><label><span data-i18n="settings.customColor">Custom color</span><input id="accent-color" type="color" value="#2f98ff"></label><label><span data-i18n="settings.hex">Hex code</span><input id="accent-hex" inputmode="text" maxlength="7" pattern="#[0-9A-Fa-f]{6}" value="#2F98FF"></label><button type="button" class="btn btn-outline reset-accent" id="reset-accent" data-i18n="settings.defaultAccent">NTC default</button></div><input id="settings-appearance" type="hidden" value="oled-blue"><small data-i18n="settings.accentHint"></small></fieldset><div class="preference-row"><label><input id="notify-listings" type="checkbox"> <span data-i18n="settings.listingNotices">Listing notifications</span></label><label><input id="notify-messages" type="checkbox"> <span data-i18n="settings.messageNotices">Message notifications</span></label></div><button class="btn btn-primary" id="save-settings" data-i18n="settings.save">Save changes →</button></form><form id="password-form" class="password-form"><p class="eyebrow" data-i18n="settings.security">SECURITY</p><h3 data-i18n="settings.changePassword">Change password</h3><label><span data-i18n="settings.currentPassword">Current password</span><input name="current_password" type="password" minlength="8"></label><label><span data-i18n="settings.newPassword">New password</span><input name="new_password" type="password" minlength="8"></label><button class="btn btn-outline" ${REMOTE_MODE?'':'disabled'} data-i18n="settings.updatePassword">Update password</button>${REMOTE_MODE?'':'<small data-i18n="settings.passwordUnavailable"></small>'}</form></section></div>`);
async function prepareSettings(){
  if(!user()){navigate(authPath('login','/einstellungen'));toast.warning(t('toast.loginFirst'));return;}
  let profile=ensureLocalProfile();
  q('#settings-name').value=profile.name||'';q('#settings-bio').value=profile.bio||'';q('#settings-email').value=profile.email||'';q('#settings-visibility').value=profile.profile_visibility||'public';q('#settings-language').value=profile.language||I18N.DEFAULT_LANGUAGE;q('#settings-currency').value=profile.currency||I18N.DEFAULT_CURRENCY;settingsOriginalAppearance=normalizeAppearance(profile.appearance);setAppearanceControls(settingsOriginalAppearance);q('#notify-listings').checked=profile.notify_listings!==false;q('#notify-messages').checked=profile.notify_messages!==false;q('#bio-count').textContent=q('#settings-bio').value.length+' / 280';
  q('#avatar-preview').innerHTML=profileAvatar(profile)?'<img src="'+esc(profileAvatar(profile))+'" alt="'+esc(t('settings.avatarAlt'))+'">':'◉';I18N.apply(q('#settings-modal'));
}
document.body.insertAdjacentHTML('beforeend','<div class="modal" id="admin-modal"><div class="modal-backdrop" data-close></div><section class="modal-panel admin-panel"><button class="close-modal" data-close>×</button><p class="eyebrow" data-i18n="admin.eyebrow"></p><h2><span data-i18n="admin.headingLead"></span><em data-i18n="admin.headingAccent"></em></h2><p class="admin-intro" data-i18n="admin.intro"></p><div class="admin-summary"><div><b id="admin-account-count">–</b><span data-i18n="admin.accounts"></span></div><div><b id="admin-listing-count">–</b><span data-i18n="admin.listings"></span></div></div><div class="admin-section-heading"><h3 data-i18n="admin.manage"></h3><span data-i18n="admin.manageHint"></span></div><div id="admin-accounts" class="admin-account-list"></div><div class="admin-section-heading"><h3 data-i18n="admin.activity"></h3><span data-i18n="admin.activityHint"></span></div><div id="admin-activity" class="activity-list"></div></section></div>');
function activityLabel(action){return t('activity.'+action);}
function adminAccountRow(account){const self=String(account.id)===String(user()?.id),status=accountBanStatus(account),action=account.is_admin||self?'<span class="admin-account-protected">'+esc(t('admin.protected'))+'</span>':'<a class="btn btn-outline" data-route href="/verwaltung/konten/'+encodeURIComponent(String(account.id))+'/sperren">'+esc(t(account.ban_active?'admin.editSuspension':'admin.suspend'))+'</a>';return '<article class="admin-account-row"><div><strong>'+esc(account.name)+'</strong><span>'+esc(account.email)+'</span></div><b class="'+(account.ban_active?'status-banned':'status-active')+'">'+esc(status)+'</b>'+action+'</article>';}
async function loadAdmin(){if(!REMOTE_MODE||!user()?.is_admin){toast.warning(t('admin.only'));return;}I18N.apply(q('#admin-modal'));q('#admin-activity').textContent=t('admin.loading');q('#admin-accounts').textContent=t('admin.loading');try{const data=await api('admin_overview');adminOverviewCache={...data,accounts:data.accounts||[],activity:data.activity||[]};q('#admin-account-count').textContent=data.account_count||0;q('#admin-listing-count').textContent=data.listing_count||0;const accounts=adminOverviewCache.accounts,activities=adminOverviewCache.activity;q('#admin-accounts').innerHTML=accounts.length?accounts.map(adminAccountRow).join(''):'<p>'+esc(t('admin.noAccounts'))+'</p>';q('#admin-activity').innerHTML=activities.length?activities.map(entry=>'<div class="activity-entry"><strong>'+esc(entry.user_name)+'</strong><span>'+esc(activityLabel(entry.action))+(entry.target?' · '+esc(entry.target):'')+(entry.reason?' · '+esc(t('admin.reason',{reason:entry.reason})):'')+'</span><time>'+esc(I18N.formatDate(entry.created_at,{dateStyle:'short',timeStyle:'short'}))+'</time></div>').join(''):'<p>'+esc(t('admin.noActivity'))+'</p>';}catch(error){q('#admin-accounts').textContent=error.message;q('#admin-activity').textContent=error.message;toast.error(error.message);}}
q('#settings-bio').addEventListener('input',e=>q('#bio-count').textContent=e.target.value.length+' / 280');
q('#accent-swatches').addEventListener('click',e=>{const button=e.target.closest('[data-accent]');if(button)setAppearanceControls(button.dataset.accent,true);});
q('#accent-color').addEventListener('input',e=>setAppearanceControls('custom:'+e.target.value.toUpperCase(),true));
q('#accent-hex').addEventListener('input',e=>{const raw=e.target.value.trim(),hex=(raw.startsWith('#')?raw:'#'+raw).toUpperCase();e.target.classList.toggle('invalid',!validHexColor(hex));if(validHexColor(hex))setAppearanceControls('custom:'+hex,true);});
q('#reset-accent').addEventListener('click',()=>setAppearanceControls('oled-blue',true));
q('#settings-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.submitter,language=q('#settings-language').value,currency=q('#settings-currency').value;button.disabled=true;try{let profile;if(REMOTE_MODE&&apiSession?.token){const previousProfile=apiSession.user;profile=(await api('me_settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({display_name:q('#settings-name').value.trim(),bio:q('#settings-bio').value.trim(),appearance:q('#settings-appearance').value,profile_visibility:q('#settings-visibility').value,notify_listings:q('#notify-listings').checked,notify_messages:q('#notify-messages').checked,language,currency})})).profile;profile=await hydrateProfile(profile,previousProfile);replaceRemoteProfile(profile);}else{profile=ensureLocalProfile();profile.name=q('#settings-name').value.trim();profile.bio=q('#settings-bio').value.trim();profile.appearance=q('#settings-appearance').value;profile.profile_visibility=q('#settings-visibility').value;profile.language=language;profile.currency=currency;profile.notify_listings=q('#notify-listings').checked;profile.notify_messages=q('#notify-messages').checked;profile.updated_at=new Date().toISOString();save();}updateOwnerProfile(profile);I18N.setPreferences({language:profile.language,currency:profile.currency});renderCreateOptionalFields();settingsOriginalAppearance=normalizeAppearance(profile.appearance);renderAccount();render();renderRoute();toast.success(t('toast.settingsSaved'));}catch(error){toast.error(error.message);}finally{button.disabled=false;}});
q('#avatar-input').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>2097152){toast.warning(t('toast.avatarTooLarge'));e.target.value='';return;}if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast.warning(t('toast.avatarTypes'));e.target.value='';return;}try{let profile;if(REMOTE_MODE&&apiSession?.token){const form=new FormData();form.append('avatar',file);profile=await hydrateProfile((await api('me_avatar',{method:'POST',body:form})).profile);replaceRemoteProfile(profile);}else{const image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});profile=ensureLocalProfile();profile.avatar_url=image;if(!save())return;}updateOwnerProfile(profile);q('#avatar-preview').innerHTML='<img src="'+esc(profileAvatar(profile))+'" alt="'+esc(t('settings.avatarAlt'))+'">';renderAccount();toast.success(t('toast.avatarSaved'));}catch(error){toast.error(t('toast.avatarFailed'));}finally{e.target.value='';}});
q('#delete-avatar').addEventListener('click',async()=>{const button=q('#delete-avatar');if(button.disabled)return;button.disabled=true;await confirmAction({tone:'danger',title:t('dialog.removeAvatarTitle'),message:t('dialog.removeAvatarMessage'),detail:t('dialog.removeAvatarDetail'),confirmLabel:t('dialog.removeAvatarConfirm')},async()=>{let profile;if(REMOTE_MODE&&apiSession?.token){profile=(await api('me_avatar_delete',{method:'POST'})).profile;profile.avatar_object_url='';replaceRemoteProfile(profile);}else{profile=ensureLocalProfile();profile.avatar_url='';if(!save())throw new Error(t('toast.storageFull'));}updateOwnerProfile(profile);q('#avatar-preview').textContent='◉';renderAccount();toast.success(t('toast.avatarRemoved'));});button.disabled=false;});
q('#password-form').addEventListener('submit',async e=>{e.preventDefault();if(!REMOTE_MODE||!apiSession?.token)return;const button=e.submitter;if(button.disabled)return;button.disabled=true;const payload=Object.fromEntries(new FormData(e.target));await confirmAction({tone:'warning',title:t('dialog.passwordTitle'),message:t('dialog.passwordMessage'),detail:t('dialog.passwordDetail'),confirmLabel:t('dialog.passwordConfirm')},async()=>{const data=await api('me_password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});apiSession=data;persistRemoteSession();await refreshRemote(true);e.target.reset();toast.success(t('toast.passwordUpdated'));});button.disabled=false;});
document.addEventListener('submit',async e=>{if(!REMOTE_MODE||!['login-form','register-form'].includes(e.target.id))return;e.preventDefault();e.stopImmediatePropagation();const destination=postAuthPath(),button=e.submitter;button.disabled=true;try{const action=e.target.id==='login-form'?'login':'register';const data=await api(action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});apiSession=data;sessionId=null;remoteListingsReady=false;localStorage.removeItem(KEYS.session);applyUserPreferences(apiSession.user);persistRemoteSession();await refreshRemote(true);pollNotifications();resetAuthForms();renderAccount();close();navigate(destination,true);toast.success(t('toast.welcome',{name:apiSession.user.name}));}catch(error){if(unavailable(error))serverStatus(false);toast.error(error.message);}finally{button.disabled=false;}},true);
restoreExchangeRates();renderCreateOptionalFields();renderAccount();render();renderRoute();if(REMOTE_MODE){startNotificationPolling();loadExchangeRates();refreshRemote().then(()=>pollNotifications()).catch(()=>{});}
